using System;
using System.Runtime.InteropServices;
public static class Rot {
  [DllImport("oleaut32.dll")]
  static extern int GetActiveObject(ref Guid rclsid, IntPtr reserved, [MarshalAs(UnmanagedType.Interface)] out object obj);
  public static object Get(string progId) {
    var clsid = Type.GetTypeFromProgID(progId).GUID;
    object o;
    int hr = GetActiveObject(ref clsid, IntPtr.Zero, out o);
    if (hr != 0) Marshal.ThrowExceptionForHR(hr);
    return o;
  }
}
'@
$sw = [Rot]::Get('SldWorks.Application')
$doc = $sw.ActiveDoc
if ($null -eq $doc) { throw 'NO_ACTIVE_DOC' }
$eq = $doc.GetEquationMgr()
$out = @()
for ($i = 0; $i -lt $eq.GetCount(); $i++) {
  $out += [pscustomobject]@{ i = $i; equation = $eq.Equation($i) }
}
$out | ConvertTo-Json -Depth 4
"}

